#include <stdio.h>

int isLeap(int y) {
    return (y % 400 == 0) || (y % 4 == 0 && y % 100 != 0);
}

int main() {
    int d, m, y;
    if (scanf("%d/%d/%d", &d, &m, &y) == 3) {
        if (y < 1900 || y > 9999 || m < 1 || m > 12) {
            printf("Invalid\n");
            return 0;
        }
        int mdays[] = {0, 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};
        if (isLeap(y)) mdays[2] = 29;
        if (d >= 1 && d <= mdays[m]) printf("Valid\n");
        else printf("Invalid\n");
    }
    return 0;
}

