const fs = require('fs');

function isLeap(y) {
    return (y % 400 === 0) || (y % 4 === 0 && y % 100 !== 0);
}

function main() {
    const s = fs.readFileSync(0, 'utf-8').trim();
    if (s.length > 0) {
        const [d, m, y] = s.split('/').map(Number);
        if (y < 1900 || y > 9999 || m < 1 || m > 12) {
            console.log("Invalid");
            return;
        }
        const mdays = [0, 31, isLeap(y) ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
        if (d >= 1 && d <= mdays[m]) console.log("Valid");
        else console.log("Invalid");
    }
}

main();

